import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import type { Person } from '../people/people';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it
 *  PENDING until a steward approves (SETTLED) or rejects (OPEN) it; a DRAFT, OPEN or PENDING claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A person's claim: the amount with two decimals, the date (yyyy-mm-dd), a note (may be empty), its status,
 *  its number (sheet-wide digits, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, the due fixed when it was settled
 *  (null when not settled, or its grade had no rate then: its due follows the rates), and who opened it
 *  (null while a draft), whether its person's last statement bound it (it counted then) and the figure it bound
 *  it to (null when not bound, or n/a then: its due stays live), and for a correction (a negative amount) the
 *  number of the SETTLED claim of the same person it corrects (null otherwise). */
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: string | null; settledDue: string | null; openedBy: string | null; stated: boolean;
  statedDue: string | null; corrects: string | null };

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED ones do. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim is still to be settled: OPEN or PENDING (it goes overdue, and a hold takes it out of the totals). */
export function unsettled(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** The claims that count in the live totals among these: those that count, except the OPEN or PENDING claims of a person
 *  (among the people given) who is on hold; their SETTLED claims still count. */
export function live(claims: Claim[], people: Person[]): Claim[] {
  const held = new Set(people.filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => counts(c) && !(unsettled(c) && held.has(c.personId)));
}

/** A claim's due-by (yyyy-mm-dd): its date plus the terms in days. */
export function dueBy(claim: Claim, terms: number): string {
  const d = new Date(`${claim.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string): boolean {
  return unsettled(claim) && today !== '' && dueBy(claim, terms) < today;
}

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** The id of the claim whose editor is open ('' when each person's claim form adds a new claim). */
export function useEditingClaim() {
 *  the grade in force on each claim's date and on the sheet's today. */
export function personDueTotal(person: Person, claims: Claim[], rates: Rate[], today: string, floor: string,
    late: Late): string {
  return personDue(live(claims.filter((c) => c.personId === person.id), [person]),
    (d) => rateOn(rates, gradeOn(person, d), d), rateOn(rates, gradeOn(person, today), today), floor, late);
}

/** What the late charge follows: the sheet's terms in days, its late percent (two decimals) and its today; and
 *  how a claim's live figures round: the policy date (the policy-date setting, else the sheet's today; '' while
 *  loading) and the dates of the sheet's numbered claims (a correction rounds by the claim it corrects). */
export type Late = { terms: number; pct: string; today: string; policy: string; numbered: Map<string, string> };

/** Whether a claim's live figures round half up: it (a correction: the claim it corrects) is dated before the
 *  policy date; else they round half to even. */
export function roundsUp(claim: Claim, late: Late): boolean {
  const date = claim.corrects !== null ? late.numbered.get(claim.corrects) ?? claim.date : claim.date;
  return late.policy !== '' && date < late.policy;
}

/** A claim's due: the one fixed when it was settled (its late charge frozen in), else its figure — the one its
 *  person's last statement bound it to (not while it is PENDING: then it is live), else live on its amount at the rate, raised to the sheet's floor when
 *  below it — with the late charge on that figure added on top. A correction (a negative amount) has no floor
 *  and no late charge. */
export function claimDue(claim: Claim, rate: string | undefined, floor: string, late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const correction = toCents(claim.amount) < 0n;
  const live = dueOn(claim.amount, rate, roundsUp(claim, late));
  const bound = claim.status === 'PENDING' ? null : claim.statedDue;
  const figure = bound ?? (correction ? live : floored(live, floor));
  if (correction) return figure;
  return figure === 'n/a' ? figure : fromCents(toCents(figure) + toCents(lateCharge(claim, figure, late)));
}

const DAY_MS = 24 * 60 * 60 * 1000;

/** The late charge on a claim whose figure is `figure`: the late percent of it for every full 30 days the
 *  claim is overdue (past its due-by, on the sheet's today), rounded like the claim's due; 0.00 when not overdue, or a
 *  correction (a negative amount). */
export function lateCharge(claim: Claim, figure: string, late: Late): string {
  if (!overdue(claim, late.terms, late.today) || toCents(claim.amount) < 0n) return '0.00';
  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(claim, late.terms)}T00:00:00Z`)) / DAY_MS);
  const periods = BigInt(Math.floor(days / 30));
  return dueOn(figure, fromCents(toCents(late.pct) * periods), roundsUp(claim, late));
}

/** A live due raised to the floor when below it; 'n/a' stays 'n/a'. */
export function floored(due: string, floor: string): string {
  return due === 'n/a' || toCents(due) >= toCents(floor) ? due : fromCents(toCents(floor));
}

